{
  "case_id": "C06",
  "audience": "General public with secondary-school science literacy",
  "target_duration_s": 60,
  "beats": [
    {
      "beat": "Hook",
      "narration": "Can the microbes in your gut change how much fat you carry? Scientists test this by transplanting gut bacteria from one mouse into another that was raised with no microbes of its own.",
      "on_screen": "Simple diagram: donor mouse gut bacteria transferred into a germ-free recipient mouse",
      "claim_refs": ["Background", "Methods"]
    },
    {
      "beat": "The headline result",
      "narration": "In this study, recipients given bacteria from a lean donor gained twenty-four percent less fat over eight weeks than those given bacteria from an obese donor. Twenty mice per group, and a convincingly small p-value.",
      "on_screen": "Bar chart: lean-donor vs obese-donor fat mass, -24%, p = 0.003",
      "claim_refs": ["Abstract", "Results (main text)"]
    },
    {
      "beat": "The catch in the supplement",
      "narration": "But that headline used only one donor pair. Three more pairs sit in the supplementary materials, and they disagree: minus six percent, plus three, minus nineteen. Pool all four and the effect shrinks to about minus eleven percent, with a range that includes no effect at all.",
      "on_screen": "Four donor pairs plotted side by side, then pooled estimate with confidence interval crossing zero",
      "claim_refs": ["Supplementary S3"]
    },
    {
      "beat": "It may be the food, not the bugs",
      "narration": "There is a second control in the supplement too. When the mice were fed matched amounts of food, the difference nearly vanished: four percent, not statistically significant. So much of the original effect looks like the mice simply eating different amounts.",
      "on_screen": "Side-by-side: free feeding -24% vs pair-fed -4%, p = 0.55; food bowl icon",
      "claim_refs": ["Supplementary S2", "Methods"]
    },
    {
      "beat": "Takeaway",
      "narration": "The paper concludes the microbiota drives fat gain. The supplement suggests a smaller, shakier story. When a result rests on one comparison and the controls are filed at the back, it is worth reading to the end.",
      "on_screen": "Text card: 'One donor pair is not four. Check the supplement.'",
      "claim_refs": ["Discussion", "Conclusion", "Supplementary S2", "Supplementary S3"]
    }
  ]
}
